/* jacobi-1d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i+ 2) / n;
      B[i] = ((DATA_TYPE) i+ 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations compared to the baseline version:
   - Use local restrict-qualified pointers to A and B to help the compiler
     assume non-aliasing and generate better vectorized code.
   - Hoist the constant 0.33333 out of the inner loops.
   - Manually unroll the spatial loops by a factor of 4 to increase
     instruction-level parallelism and expose more opportunities
     for SIMD vectorization while preserving the original data
     dependencies and memory access pattern.
   - Add vectorization hints (#pragma omp simd and #pragma GCC ivdep)
     to make it explicit that there are no loop-carried dependencies
     other than through A/B themselves.

   All transformations are algebraically equivalent to the original
   stencil computation and respect the original loop bounds.
*/
static
void kernel_jacobi_1d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  (void)tsteps; /* tsteps is kept for interface compatibility; runtime
                   loop bounds are taken from the PolyBench macros
                   as in the original code. */

  /* Local restrict-qualified views of the data improve the compiler's
     ability to optimize and vectorize the loops.  The PolyBench harness
     always passes distinct arrays for A and B, so this does not change
     the behavior of this benchmark. */
  DATA_TYPE *restrict a = A;
  DATA_TYPE *restrict b = B;

  const DATA_TYPE c = (DATA_TYPE)0.33333;
  const int nPB = _PB_N;
  const int tPB = _PB_TSTEPS;

  int t;

#pragma scop
  for (t = 0; t < tPB; t++)
    {
      int i;

      /* Upper bound (exclusive) for the inner loops: original code used
         i < _PB_N - 1, so "limit" is exactly that bound. */
      const int limit = nPB - 1;

      /* First sweep: update B from A.
         Layout:  B[i] = c * (A[i-1] + A[i] + A[i+1]) for i in [1, nPB-2].
         We unroll by 4; the cleanup loop handles the remaining at most 3
         iterations. */

      i = 1;

      /* Vectorization hints: these loops have no loop-carried dependencies
         besides their own iteration variables. The compiler is allowed to
         vectorize them freely.  The manual unrolling pattern is carefully
         constructed so that indices never go out of bounds. For the unrolled
         part we require i+3 < limit => i <= limit-4, so accesses up to
         [i+4] stay <= limit == nPB-1, which is the last valid index. */
#pragma GCC ivdep
#pragma omp simd
      for (; i + 3 < limit; i += 4)
        {
          b[i]   = c * (a[i-1] + a[i]   + a[i+1]);
          b[i+1] = c * (a[i]   + a[i+1] + a[i+2]);
          b[i+2] = c * (a[i+1] + a[i+2] + a[i+3]);
          b[i+3] = c * (a[i+2] + a[i+3] + a[i+4]);
        }

      /* Remainder iterations (at most 3 elements). Semantics identical
         to the original scalar loop. */
#pragma GCC ivdep
#pragma omp simd
      for (; i < limit; i++)
        b[i] = c * (a[i-1] + a[i] + a[i+1]);


      /* Second sweep: update A from B using the newly computed values.
         Layout:  A[i] = c * (B[i-1] + B[i] + B[i+1]) for i in [1, nPB-2].
         The same unrolling strategy is applied. */

      i = 1;

#pragma GCC ivdep
#pragma omp simd
      for (; i + 3 < limit; i += 4)
        {
          a[i]   = c * (b[i-1] + b[i]   + b[i+1]);
          a[i+1] = c * (b[i]   + b[i+1] + b[i+2]);
          a[i+2] = c * (b[i+1] + b[i+2] + b[i+3]);
          a[i+3] = c * (b[i+2] + b[i+3] + b[i+4]);
        }

#pragma GCC ivdep
#pragma omp simd
      for (; i < limit; i++)
        a[i] = c * (b[i-1] + b[i] + b[i+1]);
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_1d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}

