   including the call and return. */
static
void kernel_jacobi_1d [[gnu::flatten, gnu::noinline]] (int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  /* Use local restrict-qualified, assumed-aligned pointers to help
   * the compiler generate efficient vectorized code. All accesses in
   * this kernel go through these aliases, so the aliasing information
   * is fully exploitable. */
  DATA_TYPE * __restrict a = A;
  DATA_TYPE * __restrict b = B;

#if defined(__GNUC__) || defined(__clang__)
  a = (DATA_TYPE * __restrict)__builtin_assume_aligned(a, 64);
  b = (DATA_TYPE * __restrict)__builtin_assume_aligned(b, 64);
#endif

  /* Effective problem size used inside the SCoP. We follow the
   * original PolyBench style of using the _PB_* macros. */
  const int n_eff = _PB_N;
  const int start = 1;
  const int end   = n_eff - 2; /* last interior index */

  /* Precompute loop-unrolling bounds once; they do not depend on t. */
  const int unroll_factor = 8;
  int i_unrolled_end = start;

  if (end >= start)
    {
      const int count       = end - start + 1; /* number of interior points */
      const int unrolled_n  = (count / unroll_factor) * unroll_factor;
      i_unrolled_end        = start + unrolled_n;
    }

  /* Constant stencil coefficient; keeping the value identical to the
   * original literal (0.33333) preserves numerical behavior. */
  const DATA_TYPE c = (DATA_TYPE)0.33333;

  int t;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      /* First sweep: B[i] = c * (A[i-1] + A[i] + A[i+1]) for 1 <= i <= n_eff-2 */
      if (end >= start)
	{
	  int i = start;

	  /* Vectorization-friendly, manually unrolled loop over the bulk
	   * of the domain. The unrolled body uses only indices in
	   * [0, n_eff-1], so no out-of-bounds accesses occur. */
#pragma GCC ivdep
#pragma GCC unroll 8
	  for (; i < i_unrolled_end; i += unroll_factor)
	    {
	      b[i]   = c * (a[i-1] + a[i]   + a[i+1]);
	      b[i+1] = c * (a[i]   + a[i+1] + a[i+2]);
	      b[i+2] = c * (a[i+1] + a[i+2] + a[i+3]);
	      b[i+3] = c * (a[i+2] + a[i+3] + a[i+4]);
	      b[i+4] = c * (a[i+3] + a[i+4] + a[i+5]);
	      b[i+5] = c * (a[i+4] + a[i+5] + a[i+6]);
	      b[i+6] = c * (a[i+5] + a[i+6] + a[i+7]);
	      b[i+7] = c * (a[i+6] + a[i+7] + a[i+8]);
	    }

	  /* Clean up any remaining iterations (at most unroll_factor-1). */
	  for (; i <= end; i++)
	    b[i] = c * (a[i-1] + a[i] + a[i+1]);
	}

      /* Second sweep: A[i] = c * (B[i-1] + B[i] + B[i+1]) for 1 <= i <= n_eff-2 */
      if (end >= start)
	{
	  int i = start;

#pragma GCC ivdep
#pragma GCC unroll 8
	  for (; i < i_unrolled_end; i += unroll_factor)
	    {
	      a[i]   = c * (b[i-1] + b[i]   + b[i+1]);
	      a[i+1] = c * (b[i]   + b[i+1] + b[i+2]);
	      a[i+2] = c * (b[i+1] + b[i+2] + b[i+3]);
	      a[i+3] = c * (b[i+2] + b[i+3] + b[i+4]);
	      a[i+4] = c * (b[i+3] + b[i+4] + b[i+5]);
	      a[i+5] = c * (b[i+4] + b[i+5] + b[i+6]);
	      a[i+6] = c * (b[i+5] + b[i+6] + b[i+7]);
	      a[i+7] = c * (b[i+6] + b[i+7] + b[i+8]);
	    }

	  for (; i <= end; i++)
	    a[i] = c * (b[i-1] + b[i] + b[i+1]);
	}
    }
#pragma endscop

}


