 * Optimizations applied:
 *  - Use restrict-qualified local pointers for A and B to rule out aliasing.
 *  - Use __builtin_assume_aligned with POLYBENCH_DATA_ALIGN to tell
 *    the compiler about alignment, improving auto-vectorization.
 *  - Hoist constants and bounds out of inner loops.
 *  - Add GCC vectorization/unrolling hints on the hot inner loops.
 *  - Preserve the original algorithm and boundary conditions exactly.
 */
static
void kernel_jacobi_1d[[gnu::flatten, gnu::noinline]](int tsteps,
                                                     int n,
                                                     DATA_TYPE POLYBENCH_1D(A,N,n),
                                                     DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

  /* Local restrict-qualified, alignment-hinted pointers to improve
   * memory access optimization and vectorization.
   */
  DATA_TYPE *restrict A_local = A;
  DATA_TYPE *restrict B_local = B;

#ifdef POLYBENCH_DATA_ALIGN
  /* PolyBench allocates with explicit alignment; communicate this to
   * the compiler so it can generate aligned vector loads/stores.
   * __builtin_assume_aligned does not change runtime behavior; it
   * only guides optimization. The cast keeps the restrict qualifier.
   */
  A_local = (DATA_TYPE *restrict)__builtin_assume_aligned(A_local, POLYBENCH_DATA_ALIGN);
  B_local = (DATA_TYPE *restrict)__builtin_assume_aligned(B_local, POLYBENCH_DATA_ALIGN);
#endif

  /* Hoist frequently used constants/bounds out of loops. */
  const DATA_TYPE c0 = (DATA_TYPE)0.33333;
  const int T = _PB_TSTEPS; /* use PolyBench-sanitized values, as in original */
  const int Np = _PB_N;
  const int Nm1 = Np - 1;   /* last interior index + 1 */

#pragma scop
  for (t = 0; t < T; t++)
    {
      /* First Jacobi sweep: A -> B
       *
       * The interior points 1..Nm1-1 are updated; boundaries 0 and Nm1
       * remain unchanged, exactly as in the original code.
