#pragma GCC ivdep          /* ignore assumed dependencies to aid vectorization */
#pragma GCC unroll 8       /* encourage a moderate unroll factor */
      for (i = 1; i < Nm1; i++)
        B_local[i] = c0 * (A_local[i-1] + A_local[i] + A_local[i + 1]);

      /* Second Jacobi sweep: B -> A */
#pragma GCC ivdep
#pragma GCC unroll 8
      for (i = 1; i < Nm1; i++)
        A_local[i] = c0 * (B_local[i-1] + B_local[i] + B_local[i + 1]);
    }
#pragma endscop
}


