 *   - Introduce local `restrict` pointers `a` and `b` so the compiler
 *     can assume A and B do not overlap, enabling more aggressive
 *     vectorization and reordering.
 *   - Hoist constants (`c`, loop bounds) out of the inner loops.
 *   - Use `#pragma GCC ivdep` and `#pragma GCC unroll` to encourage
 *     SIMD vectorization and unrolling on the hot loops.
 *
 * The numerical algorithm (1D Jacobi with fixed boundary values) and
 * all array index ranges are unchanged.
 */
static
void kernel_jacobi_1d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
