  /* Local aliases with restrict to help the optimizer: in PolyBench
   * these arrays are always allocated separately and never overlap.
   */
  DATA_TYPE * restrict a = A;
  DATA_TYPE * restrict b = B;

  /* Hoist PolyBench loop bounds into local constants so the compiler
   * sees them as simple scalar values inside the hot loops.
